export function sample() {
  const geography={schema_version:1,kind:'stats-map/geography',id:'areas',revision:'r1',title:'Synthetic areas',default_locale:'en',anchor_policy:{method:'interior-point',version:1},coordinate_space:{type:'cartesian',units:'u',y_direction:'up'},levels:[{id:'area',label:'Area'}],regions:[{id:'a',label:'A',level_id:'area'},{id:'b',label:'B',level_id:'area'}],features:{type:'FeatureCollection',features:['a','b'].map((id,i)=>({type:'Feature',id:`f${id}`,properties:{role:'region',region_id:id},geometry:{type:'Polygon',coordinates:[[[i*3,0],[i*3+2,0],[i*3+2,2],[i*3,2],[i*3,0]],[[i*3+.5,.5],[i*3+.5,1],[i*3+1,1],[i*3+1,.5],[i*3+.5,.5]]]}}))}};
  const dataset={schema_version:1,kind:'stats-map/dataset',id:'amounts',revision:'r1',title:'Synthetic amounts',scope_note:'synthetic',geography_ref:{id:geography.id,revision:geography.revision},periods:[{id:'t',label:'T',order:0}],units:[{id:'u',label:'items',dimension:'count'}],metrics:[{id:'n',label:'Amount',value_type:'number',aggregation:'sum'}],scopes:[{id:'all',description:'same scope'}],series:['one','two','total'].map(id=>({id,label:id,metric_id:'n',unit_id:'u',scope_id:'all',measure_type:'actual',review_status:'reviewed'})),observations:[]};
  for(const [region,values] of [['a',[10,30,100]],['b',[40,60,100]]])values.forEach((value,i)=>dataset.observations.push({id:`${region}-${i}`,series_id:['one','two','total'][i],region_id:region,period_id:'t',status:'value',value}));
  return {geography,dataset};
}
